<script lang="ts">
	// What homology sees of a knot. Thicken the knot K into a solid tube N; the
	// rest of space is the complement E, and N and E meet in a torus. On that
	// torus live two loops: the meridian μ, once round the tube, and the
	// longitude λ, once along it, turned so that it does not link K. Mayer–
	// Vietoris turns this picture into H₁(complement) ≅ ℤ, generated by μ, for
	// every knot.
	import { untrack } from 'svelte';
	import Scene3D, { type SceneContext, type LabelHandle } from '$lib/components/three/Scene3D.svelte';
	import Segmented from '$lib/components/ui/Segmented.svelte';
	import TeX from '$lib/components/prose/TeX.svelte';
	import { glassMesh, glowTube, setGlassFade, tickMaterials, disposeTree } from '$lib/three/materials';
	import { tex } from '$lib/katex/render';
	import { figureEight } from '$lib/knots/curves';
	import { roundTrefoil } from '$lib/knots/table';
	import { resample } from '$lib/knots/relax';
	import { meridianAt, pushOff } from '$lib/knots/framing';
	import { linkingNumber } from '$lib/figures/cohomology/poincare-duality/knots';
	import type { V3 } from '$lib/knots/diagram';
	import { closedCurve } from './kit';
	import { fovFitter } from '$lib/figures/cohomology/cup-product/bands3d';

	type Which = 'trefoil' | 'eight';
	let which = $state<Which>('trefoil');
	let show = $state<'knot' | 'tube' | 'loops'>('loops');

	const R = 0.22;
	const model = $derived.by(() => {
		const raw = which === 'trefoil' ? roundTrefoil(0.62)[0] : figureEight(0.66)[0];
		// the knot stands upright, facing the viewer
		const K = resample(raw, 360).map(([x, y, z]) => [x, y, z] as V3);
		const mu = meridianAt(K, 30, R * 1.04);
		const turns = Math.round(linkingNumber(K, pushOff(K, R * 1.04, 0)));
		const lam = pushOff(K, R * 1.04, -turns, 0.4);
		return { K, mu, lam, lkMu: linkingNumber(K, mu), lkLam: linkingNumber(K, lam), turns };
	});

	let api: { build(): void; show(): void } | null = null;
	function setup(ctx: SceneContext) {
		const { scene, THREE } = ctx;
		const root = new THREE.Group();
		scene.add(root);
		let tube: InstanceType<typeof THREE.Group> | null = null;
		let loops = new THREE.Group();
		const labels: LabelHandle[] = [];
		let fade = 1;
		function build() {
			disposeTree(root);
			root.clear();
			for (const l of labels.splice(0)) l.remove();
			const m = model;
			root.add(glowTube(closedCurve(m.K), { color: 'gold', closed: true, radius: 0.045, segments: 700, haloScale: 2.4 }));
			const tg = new THREE.TubeGeometry(closedCurve(m.K), 700, R, 28, true);
			tube = glassMesh(tg, { opacity: 0.5, grid: [180, 14], gridStrength: 0.14, hue: 0.62, brightness: 0.95 });
			root.add(tube);
			loops = new THREE.Group();
			loops.add(glowTube(closedCurve(m.mu), { color: 'rose', closed: true, radius: 0.03, segments: 120, xray: 0.4 }));
			loops.add(glowTube(closedCurve(m.lam), { color: 'teal', closed: true, radius: 0.028, segments: 700, xray: 0.4 }));
			root.add(loops);
			const mp = m.mu[16];
			labels.push(ctx.label(new THREE.Vector3(mp[0] * 1.18, mp[1] * 1.18 + 0.12, mp[2]), tex('\\mu'), { className: 'rose' }));
			const lp = m.lam[200];
			labels.push(ctx.label(new THREE.Vector3(lp[0] * 1.12, lp[1] * 1.12, lp[2] + 0.1), tex('\\lambda'), { className: 'teal' }));
			const kp = m.K[110];
			labels.push(ctx.label(new THREE.Vector3(kp[0] * 0.8, kp[1] * 0.8, kp[2] + 0.2), tex('K'), { className: 'gold' }));
			apply();
		}
		function apply() {
			const target = show === 'knot' ? 0 : 1;
			fade = target;
			if (tube) setGlassFade(tube, fade);
			loops.visible = show === 'loops';
			labels[0]?.show(show === 'loops');
			labels[1]?.show(show === 'loops');
			ctx.invalidate();
		}
		const fit = fovFitter(ctx.camera, 38, 1.2);
		const off = ctx.onFrame((t) => {
			fit();
			tickMaterials(root, t);
		});
		api = { build, show: apply };
		build();
		return {
			dispose() {
				off();
				api = null;
				for (const l of labels) l.remove();
			}
		};
	}
	$effect(() => {
		void model;
		untrack(() => api?.build());
	});
	$effect(() => {
		void show;
		untrack(() => api?.show());
	});
</script>

<div class="ml">
	<Scene3D
		{setup}
		height={420}
		animate
		camera={{ position: [0, 0.2, 6.6], fov: 38 }}
		controls={{ autoRotate: true, autoRotateSpeed: 0.35 }}
		label="A gold knot inside a translucent tube; on the tube's surface a rose loop goes once round the tube (the meridian) and a teal loop runs once along it (the longitude)."
	/>
	<div class="read ui" aria-live="polite">
		<span><TeX tex={`\\operatorname{lk}(\\mu, K) = ${Math.round(model.lkMu)}`} /></span>
		<span><TeX tex={`\\operatorname{lk}(\\lambda, K) = ${Math.abs(Math.round(model.lkLam))}`} /></span>
		<span class="dim">The longitude turns {Math.abs(model.turns)} time{Math.abs(model.turns) === 1 ? '' : 's'} round the tube to get there.</span>
	</div>
	<div class="ctl ui">
		<Segmented
			bind:value={which}
			label="Which knot"
			options={[
				{ value: 'trefoil', label: 'Trefoil' },
				{ value: 'eight', label: 'Figure-eight' }
			]}
		/>
		<Segmented
			bind:value={show}
			label="What to show"
			options={[
				{ value: 'knot', label: 'The knot' },
				{ value: 'tube', label: 'Thickened' },
				{ value: 'loops', label: 'Two loops on the tube' }
			]}
		/>
	</div>
</div>

