	.ml {
		display: grid;
	}
	.read {
		display: flex;
		flex-wrap: wrap;
		justify-content: center;
		gap: 0.3rem 1.4rem;
		font-size: 0.86rem;
		color: var(--ink-dim);
		padding: 0.2rem 1rem 0.4rem;
	}
	.dim {
		color: var(--ink-faint);
		font-size: 0.8rem;
	}
	.ctl {
		display: flex;
		flex-wrap: wrap;
		gap: 0.6rem;
		justify-content: center;
		padding: 0.2rem 0.8rem 0.9rem;
	}
</style>
